def probe(lower, upper, binary=False):
    """The same three points MATLAB builds, in the problem's own box."""
    D = len(lower)
    a = np.arange(3)[:, None]
    b = np.arange(D)[None, :]
    frac = ((a * 7 + b * 13) % 97 + 0.5) / 97
    if binary:
        # MATLAB rounds a half away from zero, numpy rounds it to even, and this
        # lattice does land on 0.5 exactly (at (i*7 + j*13) % 97 == 48).
        frac = np.floor(frac + 0.5)
    return lower + frac * (upper - lower)


def build(name):
    """The problem at its shipped defaults; M is only settable on some suites."""
    suite = name.rstrip("0123456789")
    mod = importlib.import_module(f"ddmtolab.Problems.STMO.{suite}")
    factory = getattr(getattr(mod, suite)(), name)
    if "M" in inspect.signature(factory).parameters:
        return factory(M=PLATEMO[name][2])
    return factory()



@pytest.mark.parametrize("name", sorted(PLATEMO))
def test_objectives_match_platemo(name):
    want_obj, _, M, D = PLATEMO[name]
    problem = build(name)
    info = problem.get_task_info(0)
    lower = np.ravel(info["lower_bounds"]).astype(float)
    upper = np.ravel(info["upper_bounds"]).astype(float)
    X = probe(lower, upper, binary=(name == "ZDT5"))
    obj, _ = problem.evaluate_task(0, X)
    assert np.allclose(obj.ravel(), want_obj, rtol=1e-12, atol=1e-12)


@pytest.mark.parametrize("name", sorted(PLATEMO))
def test_constraints_match_platemo(name):
    _, want_con, M, D = PLATEMO[name]
    problem = build(name)
    info = problem.get_task_info(0)
    lower = np.ravel(info["lower_bounds"]).astype(float)
    upper = np.ravel(info["upper_bounds"]).astype(float)
    X = probe(lower, upper, binary=(name == "ZDT5"))
    _, con = problem.evaluate_task(0, X)
    assert np.allclose(con.ravel(), want_con, rtol=1e-12, atol=1e-12)


@pytest.mark.parametrize("name", sorted(PLATEMO))
def test_shape_matches_platemo(name):
    _, _, M, D = PLATEMO[name]
    info = build(name).get_task_info(0)
    assert info["n_objectives"] == M
    assert info["dimension"] == D


def test_dtlz8_front_stops_at_one():
    """(1/3:gap:1) in MATLAB never passes 1; np.arange with stop 1+gap does,
    and the extra point puts (1 - temp)/4 below zero."""
    from ddmtolab.Problems.STMO.DTLZ import DTLZ8_PF

    front = DTLZ8_PF(1000, 3)
    assert front.min() >= 0.0
    assert len(front) == 199


def test_zdt3_front_is_non_dominated_and_on_the_curve():
    from ddmtolab.Problems.STMO.ZDT import ZDT3_PF

    R = ZDT3_PF(1000, 2)
    residual = np.abs(R[:, 1] - (1 - np.sqrt(R[:, 0]) - R[:, 0] * np.sin(10 * np.pi * R[:, 0])))
    assert residual.max() < 1e-12
    for i, f in enumerate(R):
        dominated = np.all(R <= f, axis=1) & np.any(R < f, axis=1)
        dominated[i] = False
        assert not dominated.any(), f"point {i} of the ZDT3 front is dominated"
